"use client";

import { Select as SelectPrimitive } from "@base-ui/react/select";
import { useRender } from "@base-ui/react/use-render";
import { CheckIcon, ChevronDownIcon, ChevronUpIcon } from "lucide-react";
import {
  Children,
  type ComponentProps,
  createContext,
  isValidElement,
  type ReactNode,
  useContext,
  useEffect,
  useInsertionEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { cn } from "../lib/cn";
import { ControlSpan } from "../lib/control-animation";
import { useStateColor } from "../lib/css-motion";
import { bindMotionParameters, motionLimits, stateIndicator } from "../lib/motion";
import { useMotionHostRef } from "../lib/motion-ref";
import { usePopupPresence } from "../lib/popup-presence";
import { stateClasses } from "../lib/popup-style";
import { useCadenceMotion, withCadenceScope } from "../lib/provider";
import { safeSelectPaint, selectColourReadable, selectColourScope } from "../lib/select-colour";
import {
  createSelectPopup,
  createSelectScope,
  type SelectCandidate,
  SelectDisplay,
  SelectMotion,
  selectOrigin,
  useSelectGeometry,
  useSelectTrigger,
} from "../lib/select-motion";

const committed = typeof window === "undefined" ? useEffect : useLayoutEffect;
const itemTypes = new WeakSet<object>();
const labelTypes = new WeakSet<object>();
const Labels = createContext<Map<unknown, ReactNode> | null>(null);
function selectStyle<S>(
  paint: React.CSSProperties | undefined,
  style: React.CSSProperties | ((state: S) => React.CSSProperties | undefined) | undefined,
) {
  return typeof style === "function" ? (state: S) => ({ ...paint, ...style(state) }) : { ...paint, ...style };
}
function collectLabels(children: ReactNode, labels = new Map<unknown, ReactNode>()) {
  Children.forEach(children, (child) => {
    if (!isValidElement(child)) return;
    if (typeof child.type !== "string" && itemTypes.has(child.type)) {
      const item = child.props as { value?: unknown; children?: ReactNode };
      if (item.value !== undefined) labels.set(item.value, item.children);
    } else {
      const nested = (child.props as { children?: ReactNode }).children;
      if (nested) collectLabels(nested, labels);
    }
  });
  return labels;
}

function measuredContent(children: ReactNode, entries: [unknown, ReactNode][] = []) {
  Children.forEach(children, (child) => {
    if (!isValidElement(child) || entries.length > motionLimits.collectionVisuals) return;
    const props = child.props as { value?: unknown; children?: ReactNode };
    const primitive = typeof props.children === "string" || typeof props.children === "number" ? props.children : null;
    if (typeof child.type !== "string" && itemTypes.has(child.type)) entries.push([props.value, primitive]);
    else if (typeof child.type !== "string" && labelTypes.has(child.type))
      entries.push([child.key ?? child.type, primitive]);
    else if (props.children) measuredContent(props.children, entries);
  });
  return entries;
}

function useOptionRevision(children: ReactNode) {
  const previous = useRef<{ entries: [unknown, ReactNode][]; revision: object }>({ entries: [], revision: {} });
  const entries = measuredContent(children);
  const known = entries.length <= motionLimits.collectionVisuals;
  const old = previous.current;
  if (
    entries.length !== old.entries.length ||
    entries.some(
      ([key, label], index) => !Object.is(key, old.entries[index]?.[0]) || !Object.is(label, old.entries[index]?.[1]),
    )
  )
    previous.current = { entries, revision: {} };
  return { revision: previous.current.revision, known };
}

/** Requests supply provenance only. Value's native store supplies accepted state. */
function Select<Value, Multiple extends boolean | undefined = false>(
  props: SelectPrimitive.Root.Props<Value, Multiple>,
) {
  const [scope] = useState(createSelectScope);
  const [, requestCommit] = useState(0);
  committed(() => {
    scope.multiple = Boolean(props.multiple);
    scope.equal = (a, b) =>
      a == null || b == null
        ? Object.is(a, b)
        : (props.isItemEqualToValue?.(a as Value, b as Value) ?? Object.is(a, b));
  });
  committed(() => {
    if (
      scope.candidate?.approved &&
      (props.multiple || (props.value !== undefined && !scope.equal(props.value, scope.candidate.value)))
    )
      scope.retire();
    else if (scope.candidate?.approved) scope.candidate.capture?.retire();
  });
  committed(() => {
    const source = scope.candidate;
    if (source && (scope.trigger !== source.trigger || !scope.trigger?.querySelector("[data-select-value-text]")))
      scope.retire();
  });
  const input = useMotionHostRef<HTMLInputElement>(props.inputRef);

  committed(() => {
    const form = input.node.current?.form;
    if (!form) return;
    let alive = true;
    const reset = (event: Event) =>
      queueMicrotask(() => {
        if (!alive || event.defaultPrevented) return;
        scope.baseline++;
        scope.retire();
        scope.handoff.cancel();
        scope.transaction.cancel();
      });
    form.addEventListener("reset", reset);
    return () => {
      alive = false;
      form.removeEventListener("reset", reset);
    };
  });
  useInsertionEffect(
    () => () => {
      scope.retire();
      scope.handoff.dispose();
      scope.transaction.close();
    },
    [scope],
  );
  return (
    <SelectMotion value={scope}>
      <Labels value={props.items ? null : collectLabels(props.children)}>
        <SelectPrimitive.Root
          {...props}
          inputRef={input.ref}
          onValueChange={(value, details) => {
            props.onValueChange?.(value, details);
            const source = scope.candidate;
            if (details.isCanceled) scope.retire();
            else if (!props.multiple && source && source.event === details.event && scope.equal(source.value, value)) {
              source.approved = true;
              requestCommit((version) => version + 1);
            } else scope.retire();
            if (details.reason === "none") {
              scope.baseline++;
              scope.handoff.cancel();
              scope.transaction.cancel();
            }
          }}
        />
      </Labels>
    </SelectMotion>
  );
}

function SelectGroup({ className, ...props }: SelectPrimitive.Group.Props) {
  return <SelectPrimitive.Group data-slot="select-group" className={stateClasses("", className)} {...props} />;
}
function SelectValue({ className, render, ...props }: SelectPrimitive.Value.Props) {
  const labels = useContext(Labels);
  const formatter =
    props.children ??
    (labels
      ? (value: unknown): ReactNode => {
          if (value == null || (Array.isArray(value) && value.length === 0)) return props.placeholder ?? null;
          if (Array.isArray(value)) return value.map((entry) => labels.get(entry) ?? (entry as ReactNode));
          return labels.get(value) ?? (value as ReactNode);
        }
      : undefined);
  return (
    <SelectPrimitive.Value
      {...props}
      className={stateClasses("block w-max", className)}
      render={(elementProps, state) => (
        <ValueSurface
          elementProps={elementProps}
          state={state}
          render={render}
          owned={typeof props.children !== "function"}
        />
      )}
    >
      {formatter}
    </SelectPrimitive.Value>
  );
}
function ValueSurface({
  elementProps,
  state,
  render,
  owned,
}: {
  elementProps: React.ComponentPropsWithRef<"span">;
  state: SelectPrimitive.Value.State;
  render: SelectPrimitive.Value.Props["render"];
  owned: boolean;
}) {
  const valueHost = useMotionHostRef<HTMLSpanElement>(elementProps.ref),
    width = useMotionHostRef<HTMLSpanElement>();
  const cm = useCadenceMotion(valueHost.node);
  const ValueSurfacePaint = useStateColor(valueHost.ref, cm, ["color"], {
    readability: safeSelectPaint(elementProps) ? "verified" : "immediate",
    readabilityGate: selectColourReadable,
    readabilityScope: selectColourScope,
  });
  useSelectGeometry(width.node, valueHost.node, elementProps.children, cm, "width", Boolean(render));
  return (
    <span
      ref={width.ref}
      data-slot="select-value"
      data-motion={cm.mode}
      className="relative block min-w-0 overflow-hidden whitespace-nowrap"
    >
      {useRender({
        defaultTagName: "span",
        render,
        state: { ...state },
        props: {
          ...elementProps,
          ...ValueSurfacePaint,
          style: { ...ValueSurfacePaint.style, ...elementProps.style },
          "data-slot": "select-value-content",
          "data-motion": cm.mode,
          children:
            owned && !render ? (
              <SelectDisplay value={elementProps.children} selected={state.value} valueLane />
            ) : (
              elementProps.children
            ),
        },
      })}
    </span>
  );
}

function SelectTrigger({
  className,
  ref,
  size = "default",
  children,
  ...props
}: SelectPrimitive.Trigger.Props & { size?: "sm" | "default" }) {
  const host = useMotionHostRef<HTMLButtonElement>(ref),
    cm = useCadenceMotion(host.node);
  useSelectTrigger(host.node, cm);
  const SelectTriggerPaint = useStateColor(
    host.ref,
    cm,
    [
      "background-color",
      "color",
      "border-top-color",
      "border-right-color",
      "border-bottom-color",
      "border-left-color",
      "box-shadow",
    ],
    {
      readability: safeSelectPaint({ className, style: props.style }) ? "verified" : "immediate",
      readabilityGate: selectColourReadable,
      readabilityScope: selectColourScope,
    },
  );
  return (
    <SelectPrimitive.Trigger
      {...props}
      data-slot="select-trigger"
      data-size={size}
      className={stateClasses(
        cn(
          "relative flex h-9 w-fit items-center justify-between gap-2 overflow-hidden rounded-md border border-input bg-transparent px-3 pr-8 text-sm whitespace-nowrap shadow-xs outline-none select-none",
          "focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50",
          "disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20",
          "data-[placeholder]:text-muted-foreground data-[size=default]:h-9 data-[size=sm]:h-8",
          "[&_[data-placeholder]]:text-muted-foreground",
          "dark:bg-input/30 dark:hover:bg-input/50 dark:aria-invalid:ring-destructive/40",
        ),
        className,
      )}
      {...SelectTriggerPaint}
      style={selectStyle(SelectTriggerPaint.style, props.style)}
    >
      {children}
      <SelectPrimitive.Icon
        render={
          <ChevronDownIcon className="pointer-events-none absolute top-1/2 right-3 size-4 -translate-y-1/2 opacity-50" />
        }
      >
        {null}
      </SelectPrimitive.Icon>
    </SelectPrimitive.Trigger>
  );
}

function SelectContent({
  className,
  children,
  side = "bottom",
  sideOffset = 4,
  align = "center",
  alignOffset = 0,
  alignItemWithTrigger = true,
  render,
  ...props
}: SelectPrimitive.Popup.Props &
  Pick<SelectPrimitive.Positioner.Props, "align" | "alignOffset" | "side" | "sideOffset" | "alignItemWithTrigger">) {
  const flow = useRef<HTMLDivElement>(null);
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Positioner
        side={side}
        sideOffset={sideOffset}
        align={align}
        alignOffset={alignOffset}
        alignItemWithTrigger={alignItemWithTrigger}
        className="isolate z-50"
      >
        <SelectPrimitive.Popup
          {...props}
          data-align-trigger={alignItemWithTrigger}
          className={stateClasses(
            "relative z-50 max-h-(--available-height) w-(--anchor-width) min-w-[8rem] origin-(--transform-origin) overflow-x-hidden overflow-y-auto rounded-md border bg-popover text-popover-foreground shadow-md outline-none",
            className,
          )}
          render={(elementProps, state) => (
            <PopupSurface
              elementProps={elementProps}
              state={state}
              render={render}
              aligned={alignItemWithTrigger}
              content={children}
              flow={flow}
            />
          )}
        >
          <SelectScrollUpButton />
          <SelectPrimitive.List ref={flow} data-slot="select-list" className="p-1">
            {children}
          </SelectPrimitive.List>
          <SelectScrollDownButton />
        </SelectPrimitive.Popup>
      </SelectPrimitive.Positioner>
    </SelectPrimitive.Portal>
  );
}
function PopupSurface({
  elementProps,
  state,
  render,
  aligned,
  content,
  flow,
}: {
  elementProps: React.ComponentPropsWithRef<"div">;
  state: SelectPrimitive.Popup.State;
  render: SelectPrimitive.Popup.Props["render"];
  aligned: boolean;
  content: ReactNode;
  flow: React.RefObject<HTMLDivElement | null>;
}) {
  const options = useOptionRevision(content);
  const host = useMotionHostRef<HTMLDivElement>(elementProps.ref),
    cm = useCadenceMotion(host.node);
  const wrap = usePopupPresence(host.node, [], false, cm, "base");
  const controller = useRef<ReturnType<typeof createSelectPopup> | null>(null),
    connected = useRef<HTMLElement | null>(null);
  const PopupSurfacePaint = useStateColor(
    host.ref,
    cm,
    [
      "background-color",
      "color",
      "border-top-color",
      "border-right-color",
      "border-bottom-color",
      "border-left-color",
      "box-shadow",
    ],
    {
      readability: safeSelectPaint(elementProps) ? "verified" : "immediate",
      readabilityGate: selectColourReadable,
      readabilityScope: selectColourScope,
    },
  );
  committed(() => {
    if (connected.current !== host.node.current) {
      controller.current?.dispose();
      controller.current = null;
      connected.current = host.node.current;
    }
    if (host.node.current && !controller.current) controller.current = createSelectPopup(host.node.current);
    controller.current?.commit({ open: state.open, enter: state.open, cm });
  });
  useInsertionEffect(() => () => controller.current?.dispose(), []);
  useSelectGeometry(
    host.node,
    flow,
    options.revision,
    cm,
    "height",
    aligned || Boolean(render) || !state.open || !options.known,
  );
  return withCadenceScope(
    cm,
    wrap(
      useRender({
        defaultTagName: "div",
        render,
        state: { ...state, slot: "select-content" },
        props: {
          ...elementProps,
          ...PopupSurfacePaint,
          style: { ...PopupSurfacePaint.style, ...elementProps.style },
          "data-slot": "select-content",
          "data-motion": cm.mode,
          inert: state.open ? elementProps.inert : true,
          "aria-hidden": state.open ? elementProps["aria-hidden"] : true,
          children: elementProps.children,
        },
      }),
    ),
  );
}

function SelectLabel({ className, ref, children, ...props }: SelectPrimitive.GroupLabel.Props) {
  const host = useMotionHostRef<HTMLDivElement>(ref),
    cm = useCadenceMotion(host.node);
  const SelectLabelPaint = useStateColor(host.ref, cm, ["color"], {
    readability: safeSelectPaint({ className, style: props.style }) ? "verified" : "immediate",
    readabilityGate: selectColourReadable,
    readabilityScope: selectColourScope,
  });
  return (
    <SelectPrimitive.GroupLabel
      {...props}
      data-slot="select-label"
      className={stateClasses("px-2 py-1.5 text-xs text-muted-foreground", className)}
      {...SelectLabelPaint}
      style={selectStyle(SelectLabelPaint.style, props.style)}
    >
      <SelectDisplay value={children} />
    </SelectPrimitive.GroupLabel>
  );
}
function SelectSeparator({ className, ref, children, ...props }: SelectPrimitive.Separator.Props) {
  const host = useMotionHostRef<HTMLDivElement>(ref),
    cm = useCadenceMotion(host.node);
  const SelectSeparatorPaint = useStateColor(host.ref, cm, ["background-color"], {
    readability: safeSelectPaint({ className, style: props.style }) ? "verified" : "immediate",
    readabilityGate: selectColourReadable,
    readabilityScope: selectColourScope,
  });
  return (
    <SelectPrimitive.Separator
      {...props}
      data-slot="select-separator"
      className={stateClasses("pointer-events-none -mx-1 my-1 h-px bg-border", className)}
      {...SelectSeparatorPaint}
      style={selectStyle(SelectSeparatorPaint.style, props.style)}
    >
      {children}
    </SelectPrimitive.Separator>
  );
}
function SelectScrollUpButton({
  className,
  ref,
  children,
  ...props
}: ComponentProps<typeof SelectPrimitive.ScrollUpArrow>) {
  const host = useMotionHostRef<HTMLDivElement>(ref),
    cm = useCadenceMotion(host.node);
  const SelectScrollUpButtonPaint = useStateColor(host.ref, cm, ["background-color", "color"], {
    readability: safeSelectPaint({ className, style: props.style }) ? "verified" : "immediate",
    readabilityGate: selectColourReadable,
    readabilityScope: selectColourScope,
  });
  return (
    <SelectPrimitive.ScrollUpArrow
      {...props}
      data-slot="select-scroll-up-button"
      className={stateClasses(
        "sticky top-0 z-[1] flex w-full cursor-default items-center justify-center bg-popover py-1",
        className,
      )}
      {...SelectScrollUpButtonPaint}
      style={selectStyle(SelectScrollUpButtonPaint.style, props.style)}
    >
      <ChevronUpIcon className="size-4" />
    </SelectPrimitive.ScrollUpArrow>
  );
}
function SelectScrollDownButton({
  className,
  ref,
  children,
  ...props
}: ComponentProps<typeof SelectPrimitive.ScrollDownArrow>) {
  const host = useMotionHostRef<HTMLDivElement>(ref),
    cm = useCadenceMotion(host.node);
  const SelectScrollDownButtonPaint = useStateColor(host.ref, cm, ["background-color", "color"], {
    readability: safeSelectPaint({ className, style: props.style }) ? "verified" : "immediate",
    readabilityGate: selectColourReadable,
    readabilityScope: selectColourScope,
  });
  return (
    <SelectPrimitive.ScrollDownArrow
      {...props}
      data-slot="select-scroll-down-button"
      className={stateClasses(
        "sticky bottom-0 z-[1] flex w-full cursor-default items-center justify-center bg-popover py-1",
        className,
      )}
      {...SelectScrollDownButtonPaint}
      style={selectStyle(SelectScrollDownButtonPaint.style, props.style)}
    >
      <ChevronDownIcon className="size-4" />
    </SelectPrimitive.ScrollDownArrow>
  );
}

function SelectItem({ className, children, onClick, ref, ...props }: SelectPrimitive.Item.Props) {
  const host = useMotionHostRef<HTMLDivElement>(ref),
    cm = useCadenceMotion(host.node),
    scope = useContext(SelectMotion);
  const SelectItemPaint = useStateColor(host.ref, cm, ["background-color", "color"], {
    readability: safeSelectPaint({ className, style: props.style }) ? "verified" : "immediate",
    readabilityGate: selectColourReadable,
    readabilityScope: selectColourScope,
  });
  return (
    <SelectPrimitive.Item
      {...props}
      data-slot="select-item"
      className={stateClasses(
        cn(
          "relative flex w-full cursor-default items-center gap-2 rounded-sm py-1.5 pr-8 pl-2 text-sm outline-hidden select-none",
          "data-highlighted:bg-accent data-highlighted:text-accent-foreground",
          "data-disabled:pointer-events-none data-disabled:opacity-50",
          "[&_svg]:pointer-events-none [&_svg]:shrink-0",
        ),
        className,
      )}
      onClick={(event) => {
        onClick?.(event);
        if (!scope || scope.multiple || event.defaultPrevented || event.currentTarget.hasAttribute("data-selected"))
          return;
        scope.retire();
        const text = event.currentTarget.querySelector<HTMLElement>(
          '[data-slot="select-item-text"] [data-slot="select-text"]',
        );
        const previous = scope.trigger?.querySelector('[data-slot="select-value"]')?.textContent ?? "";
        const capture =
          text && event.detail > 0 && !cm.reduced ? selectOrigin(text, previous, text.textContent ?? "") : null;
        const candidate: SelectCandidate = {
          capture,
          value: props.value,
          trigger: scope.trigger,
          event: event.nativeEvent,
          approved: false,
        };
        scope.candidate = candidate;
        // Base has no request token for an asynchronous controlled echo. Do not
        // lend this origin to an unrelated later equal value or retain a queue.
        queueMicrotask(() => {
          if (scope.candidate === candidate && !candidate.approved) scope.retire();
        });
      }}
      {...SelectItemPaint}
      style={selectStyle(SelectItemPaint.style, props.style)}
    >
      <SelectPrimitive.ItemText data-slot="select-item-text" className="shrink-0 whitespace-nowrap">
        <SelectDisplay value={children} />
      </SelectPrimitive.ItemText>
      <SelectPrimitive.ItemIndicator
        keepMounted
        render={(indicatorProps, state) => <SelectIndicator elementProps={indicatorProps} selected={state.selected} />}
      />
    </SelectPrimitive.Item>
  );
}
function SelectIndicator({
  elementProps,
  selected,
}: {
  elementProps: React.ComponentPropsWithRef<"span">;
  selected: boolean;
}) {
  const cm = useCadenceMotion();
  const parameters = cm.parameters(bindMotionParameters(stateIndicator, "state.morph/indicator"));
  if (parameters.kind !== "indicator") return null;
  return (
    <ControlSpan
      {...(elementProps as import("motion/react").HTMLMotionProps<"span">)}
      data-slot="select-item-indicator"
      data-motion={cm.mode}
      className={cn("absolute right-2 flex size-3.5 items-center justify-center", elementProps.className)}
      target={{ opacity: selected ? 1 : 0, scale: selected || cm.reduced ? 1 : parameters.scale }}
      transition={{ opacity: parameters.opacity, scale: parameters.spatial }}
    >
      <CheckIcon className="size-4" />
    </ControlSpan>
  );
}

itemTypes.add(SelectItem);
labelTypes.add(SelectLabel);

export {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectScrollDownButton,
  SelectScrollUpButton,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
};

"use client";

import {
  createContext,
  type ReactNode,
  useContext,
  useEffect,
  useInsertionEffect,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import { captureHandoffOrigin, createCapturedHandoff } from "./captured-handoff";
import { createInlinePresence } from "./inline-presence";
import { createMeasuredGeometry, naturalGeometry } from "./measured-geometry";
import { bindMotionParameters, geometryCompact, motionMilliseconds, presenceExit, presencePopup } from "./motion";
import { subscribeMotionEnvironment } from "./motion-environment";
import { documentPresentation, usePresentationScope } from "./motion-presence";
import { type MotionHostRef, useMotionHostRef } from "./motion-ref";
import { createMotionTransaction } from "./motion-transaction";
import { type CadenceMotion, useCadenceMotion } from "./provider";
import { createTextSnapshot, diffText } from "./text-diff";
import { nativeTextContext, proveTextLayout } from "./text-layout";
import { useTextPresentation } from "./use-text-presentation";

export type SelectCandidate = {
  capture: ReturnType<typeof captureHandoffOrigin>;
  value: unknown;
  trigger: HTMLElement | null;
  event: Event;
  approved: boolean;
  taken?: boolean;
};
export function createSelectScope() {
  const transaction = createMotionTransaction();
  return {
    transaction,
    handoff: createCapturedHandoff(transaction),
    trigger: null as HTMLElement | null,
    candidate: null as SelectCandidate | null,
    baseline: 0,
    multiple: false,
    equal: (a: unknown, b: unknown) => Object.is(a, b),
    retire() {
      this.candidate?.capture?.dispose();
      this.candidate = null;
    },
  };
}
export const SelectMotion = createContext<ReturnType<typeof createSelectScope> | null>(null);
const committed = typeof window === "undefined" ? useEffect : useLayoutEffect;
const subscribe = () => () => {};

/** Trigger and value survive the popup's presentation scope and its exit. */
export function useSelectTrigger(host: MotionHostRef<HTMLElement>, cm: CadenceMotion) {
  const scope = useContext(SelectMotion),
    parent = usePresentationScope();
  const hydration = useSyncExternalStore(
    subscribe,
    () => false,
    () => true,
  );
  const [hydrated] = useState(hydration);
  const consumed = useRef(false);
  const connection = useRef<{ node: HTMLElement; controller: ReturnType<typeof createInlinePresence> } | null>(null);
  committed(() => {
    const node = host.current;
    if (connection.current?.node !== node) {
      connection.current?.controller.dispose();
      connection.current = null;
    }
    if (!node) return;
    if (scope) scope.trigger = node;
    if (!connection.current) {
      const owner = parent ?? documentPresentation(node.ownerDocument);
      const enter =
        !consumed.current &&
        !hydrated &&
        owner.presented &&
        owner.available() &&
        !owner.node?.current?.hasAttribute("data-starting-style");
      consumed.current = true;
      connection.current = { node, controller: createInlinePresence(node) };
      connection.current.controller.commit({ present: true, enter, cm });
    } else connection.current.controller.commit({ present: true, enter: false, cm });
    host.invalidate = () => {
      connection.current?.controller.dispose();
      connection.current = null;
      scope?.handoff.cancel();
      if (scope?.trigger === node) scope.trigger = null;
    };
  });
  useEffect(() => {
    if (!parent && host.current) documentPresentation(host.current.ownerDocument).presented = true;
  });
  useInsertionEffect(
    () => () => {
      connection.current?.controller.dispose();
      scope?.handoff.cancel();
      if (scope?.trigger === host.current) scope.trigger = null;
    },
    [scope, host],
  );
}

/** Source proof is bounded, plain and tied to this actual pointer request. */
export function selectOrigin(source: HTMLElement, previous: string, next: string) {
  const diff = diffText(createTextSnapshot(previous), next);
  if (diff.immediate || diff.runs.length !== 1 || source.textContent !== next) return null;
  const run = diff.runs[0];
  if (!run?.incoming.length || !proveTextLayout(source, createTextSnapshot(next), { surfacePaint: true })) return null;
  const popup = source.closest<HTMLElement>('[data-slot="select-content"]');
  return captureHandoffOrigin(
    source,
    run.incoming.map((unit) => unit.text).join(""),
    null,
    popup?.parentElement ?? popup ?? source,
    run.after,
  );
}

/** Only primitive known display strings are enhanced; numeric option labels are identities. */
export function SelectDisplay({
  value,
  selected,
  visible = true,
  valueLane = false,
}: {
  value: ReactNode;
  selected?: unknown;
  visible?: boolean;
  valueLane?: boolean;
}) {
  return typeof value === "string" || typeof value === "number" ? (
    <SelectText value={String(value)} selected={selected} visible={visible} valueLane={valueLane} />
  ) : (
    value
  );
}
function SelectText({
  value,
  selected,
  visible,
  valueLane,
}: {
  value: string;
  selected: unknown;
  visible: boolean;
  valueLane: boolean;
}) {
  const { node, ref } = useMotionHostRef<HTMLSpanElement>();
  const cm = useCadenceMotion(node),
    scope = useContext(SelectMotion);
  const parent = usePresentationScope();
  const [entity] = useState(() => ({}));
  const baseline = useRef(scope?.baseline);
  const source = valueLane ? scope?.candidate : null;
  const accepted =
    !scope?.multiple && source?.approved && scope?.equal(selected, source.value) && scope.trigger === source.trigger;
  committed(() => {
    if (source && accepted) {
      source.capture?.retire();
      source.taken = true;
      if (scope?.candidate === source) scope.candidate = null;
    }
  });
  const text = useTextPresentation(
    node,
    value,
    cm,
    entity,
    {
      characterStagger: false,
      visible: visible && baseline.current === scope?.baseline && (parent?.available() ?? true),
      capture: accepted ? source?.capture : null,
      sourceRetired: true,
      deferHandoff: true,
    },
    valueLane ? scope?.transaction : parent?.transaction,
    valueLane ? scope?.handoff : undefined,
  );
  committed(() => {
    baseline.current = scope?.baseline;
  });
  return (
    <span ref={ref} data-slot="select-text" data-select-value-text={valueLane || undefined} data-motion={cm.mode}>
      {text}
    </span>
  );
}

/** Shared measured shell. Native allocation/alignment always has priority. */
export function useSelectGeometry(
  host: MotionHostRef<HTMLElement>,
  content: React.RefObject<HTMLElement | null>,
  value: unknown,
  cm: CadenceMotion,
  axis: "width" | "height",
  native = false,
) {
  const scope = useContext(SelectMotion);
  const [transaction] = useState(() => scope?.transaction ?? createMotionTransaction());
  const [geometry] = useState(() => createMeasuredGeometry(transaction));
  const source = useRef({}),
    baseline = useRef(scope?.baseline);
  const settings = useRef({ native });
  const connected = useRef<{ host: HTMLElement; content: HTMLElement; release(): void } | null>(null);
  committed(() => {
    settings.current = { native };
    const node = host.current,
      flow = content.current;
    if (connected.current && (connected.current.host !== node || connected.current.content !== flow)) {
      connected.current.release();
      connected.current = null;
    }
    if (node && flow && !connected.current) {
      const release = geometry.register({
        host,
        content: flow,
        axes: [axis],
        measure() {
          if (
            settings.current.native ||
            nativeTextContext(node) ||
            (axis === "height" && node.contains(node.ownerDocument.activeElement))
          )
            return null;
          const css = getComputedStyle(node),
            natural = naturalGeometry(flow);
          if (!natural || css.writingMode !== "horizontal-tb" || css.aspectRatio !== "auto") return null;
          const typed = node.computedStyleMap?.().get(axis)?.toString();
          if (typed && !["auto", "fit-content", "max-content"].includes(typed)) return null;
          const border =
            axis === "width"
              ? Number.parseFloat(css.paddingLeft) +
                Number.parseFloat(css.paddingRight) +
                Number.parseFloat(css.borderLeftWidth) +
                Number.parseFloat(css.borderRightWidth)
              : Number.parseFloat(css.paddingTop) +
                Number.parseFloat(css.paddingBottom) +
                Number.parseFloat(css.borderTopWidth) +
                Number.parseFloat(css.borderBottomWidth);
          const arrows =
            axis === "height"
              ? Array.from(node.children)
                  .filter((child) => child !== flow && child instanceof HTMLElement)
                  .reduce((sum, child) => sum + (naturalGeometry(child as HTMLElement)?.height ?? 0), 0)
              : 0;
          const size = natural[axis] + arrows + (css.boxSizing === "border-box" ? border : 0);
          if (!Number.isFinite(size)) return null;
          return { [axis]: { size, min: size, independent: true, readable: true } };
        },
      });
      // Focus had temporarily delegated the size axis to native layout. Leaving
      // it establishes today's natural baseline, not a new resize story.
      const focus = () =>
        queueMicrotask(() => {
          if (host.current === node && !node.contains(node.ownerDocument.activeElement)) geometry.settle();
        });
      node.addEventListener("focusout", focus);
      connected.current = {
        host: node,
        content: flow,
        release() {
          node.removeEventListener("focusout", focus);
          release();
        },
      };
    }
    const parameters = cm.parameters(bindMotionParameters(geometryCompact, "geometry.resize/measured"));
    if (parameters.kind === "geometry")
      geometry.commit(transaction.revision("content", value, source), {
        reduced: cm.reduced,
        transition: parameters.transition,
        available: !native && baseline.current === scope?.baseline,
      });
    baseline.current = scope?.baseline;
  });
  useInsertionEffect(
    () => () => {
      connected.current?.release();
      connected.current = null;
      geometry.dispose();
    },
    [geometry],
  );
}

/** Parameter-backed popup paint; Base UI still waits on the real native handles. */
export function createSelectPopup(node: HTMLElement) {
  const transaction = createMotionTransaction(),
    owner = transaction.register(node);
  let current: { open: boolean; cm: CadenceMotion; enter: boolean } | null = null;
  let handles: Animation[] = [],
    alive = true,
    epoch = 0,
    blocked = false;
  let lease: ReturnType<typeof owner.begin>;
  const cancel = () => {
    epoch++;
    for (const handle of handles) handle.cancel();
    handles = [];
    lease?.cancel();
  };
  const settleEntry = () => {
    if (current?.open) cancel();
  };
  for (const type of ["focusin", "pointerdown", "click", "keydown", "beforematch"])
    node.addEventListener(type, settleEntry, true);
  const unsubscribe = subscribeMotionEnvironment(node.ownerDocument, (e) => {
    blocked = e.hidden || e.immediate;
    if (blocked || (e.reduced && current?.cm.mode === "full")) cancel();
  });
  return {
    commit(input: { open: boolean; cm: CadenceMotion; enter: boolean }) {
      const previous = current;
      current = input;
      const enter = input.cm.parameters(bindMotionParameters(presencePopup, "popup.anchored/presence"));
      const exit = input.cm.parameters(bindMotionParameters(presenceExit, "exit.fade/opacity"));
      if (!alive || enter.kind !== "visual" || exit.kind !== "visual") return;
      const changed = previous ? previous.open !== input.open : input.enter;
      const downgrade = previous?.cm.mode === "full" && input.cm.reduced;
      if (!changed && !downgrade && !input.cm.disabled && input.cm.timeScale !== 0) return;
      const css = getComputedStyle(node),
        opacity = handles.length ? css.opacity : undefined;
      cancel();
      const clocks = input.open ? enter : exit;
      const immediate = blocked || input.cm.disabled || input.cm.timeScale === 0 || clocks.opacity.duration === 0;
      if (
        typeof node.animate !== "function" ||
        (input.open && (immediate || node.contains(node.ownerDocument.activeElement)))
      )
        return;
      if ((!changed && !downgrade && !immediate) || css.visibility === "hidden" || css.display === "none") return;
      // Caller opacity/transform families retain their native authority.
      if (
        node.style.opacity ||
        css.transitionProperty
          .split(",")
          .some(
            (property, index) =>
              ["all", "opacity", "transform", "scale", "translate"].includes(property.trim()) &&
              Number.parseFloat(
                css.transitionDuration.split(",")[index % css.transitionDuration.split(",").length] ?? "0",
              ) > 0,
          ) ||
        node
          .getAnimations()
          .some((a) =>
            (a.effect as KeyframeEffect | null)?.getKeyframes().some((f) => "opacity" in f || "transform" in f),
          )
      )
        return;
      const spatial = input.open && !immediate && !input.cm.reduced && css.transform === "none" && css.scale === "none";
      const revision = transaction.revision("presence", input.open, node),
        generation = epoch;
      lease = owner.begin(revision, spatial ? ["opacity", "transform"] : ["opacity"], {}, () => {
        for (const handle of handles) handle.cancel();
        handles = [];
      });
      if (!lease?.current()) return;
      handles = [
        node.animate(
          [
            { opacity: immediate ? 0 : (opacity ?? (input.open ? 0 : css.opacity)) },
            { opacity: input.open ? css.opacity : 0 },
          ],
          {
            duration: motionMilliseconds(immediate ? 0 : Number(clocks.opacity.duration)),
            easing: `cubic-bezier(${input.cm.scope.tokens.ease[input.open ? "out" : "in"].join(",")})`,
            fill: "both",
          },
        ),
      ];
      if (spatial)
        handles.push(
          node.animate([{ transform: `scale(${enter.scale})` }, { transform: "none" }], {
            duration: motionMilliseconds(Number(enter.spatial.duration)),
            easing: `cubic-bezier(${input.cm.scope.tokens.ease.out.join(",")})`,
            fill: "both",
          }),
        );
      void Promise.allSettled(handles.map((h) => h.finished)).then(() => {
        if (alive && generation === epoch && input.open) cancel();
      });
    },
    dispose() {
      alive = false;
      cancel();
      owner.dispose();
      unsubscribe();
      for (const type of ["focusin", "pointerdown", "click", "keydown", "beforematch"])
        node.removeEventListener(type, settleEntry, true);
    },
  };
}

"use client";

import { motionLimits } from "./motion";

type Neutral = { value: number; alpha: number };
type Interval = [number, number];
const contexts = new WeakMap<Document, CanvasRenderingContext2D>();

export function selectColourScope(node: Element) {
  return (
    node.closest<HTMLElement>('[data-slot="select-trigger"],[data-slot="select-content"]') ?? (node as HTMLElement)
  );
}

/** Prove this actual region against its rendered neutral backdrop and all endpoints.
 * Unknown/custom palettes settle to their native cascade, independently of other regions. */
export function selectColourReadable(node: Element) {
  const surface = backdrop(node);
  const foreground = colours(node, "color");
  const ink = composite(foreground, surface);
  if (!surface || !ink || (ink[0] <= surface[1] && ink[1] >= surface[0])) return false;
  const luminance = (v: number) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4);
  const low = ink[1] < surface[0] ? luminance(ink[1]) : luminance(surface[1]);
  const high = ink[1] < surface[0] ? luminance(surface[0]) : luminance(ink[0]);
  return (high + 0.05) / (low + 0.05) >= 4.5;
}

export function safeSelectPaint(props: { className?: unknown; style?: unknown }) {
  if (typeof props.className === "function" || typeof props.style === "function") return false;
  if (
    Object.keys(props.style ?? {}).some((key) =>
      /color|background|shadow|opacity|filter|blend|^--(?!motion-|cadence-|ease-)/i.test(key),
    )
  )
    return false;
  return !String(props.className ?? "")
    .split(/\s+/)
    .some((token) => {
      const name = token.split(":").pop() ?? "";
      return (
        /^(bg-|text-|border-|shadow-|ring-)/.test(name) &&
        !/^(?:bg-(?:transparent|input\/(?:30|50)|popover|accent|border)|text-(?:popover-foreground|accent-foreground|muted-foreground|foreground|sm|xs)|border-(?:input|ring|destructive)|shadow-(?:xs|md)|ring-(?:ring\/50|destructive\/(?:20|40)|\[3px\]))$/.test(
          name,
        )
      );
    });
}

function colours(node: Element, property: "background-color" | "color"): Neutral[] | null {
  const view = node.ownerDocument.defaultView;
  if (!view || typeof view.CanvasRenderingContext2D === "undefined") return null;
  let context = contexts.get(node.ownerDocument);
  if (!context) {
    const canvas = node.ownerDocument.createElement("canvas");
    canvas.width = canvas.height = 1;
    context = canvas.getContext("2d", { willReadFrequently: true }) ?? undefined;
    if (!context) return null;
    contexts.set(node.ownerDocument, context);
  }
  const values = [view.getComputedStyle(node).getPropertyValue(property)];
  const key = property === "color" ? "color" : "backgroundColor";
  for (const animation of node.getAnimations()) {
    if (!("transitionProperty" in animation) || animation.transitionProperty !== property) continue;
    for (const frame of (animation.effect as KeyframeEffect | null)?.getKeyframes() ?? [])
      if (typeof frame[key] === "string") values.push(frame[key]);
  }
  const result: Neutral[] = [];
  for (const value of new Set(values)) {
    if (!view.CSS.supports("color", value)) return null;
    context.clearRect(0, 0, 1, 1);
    context.fillStyle = value;
    context.fillRect(0, 0, 1, 1);
    const [r = 0, g = 0, b = 0, a = 0] = context.getImageData(0, 0, 1, 1).data;
    if (a && Math.max(r, g, b) !== Math.min(r, g, b)) return null;
    result.push({ value: (r + g + b) / (3 * 255), alpha: a / 255 });
  }
  return result;
}
function composite(colours: Neutral[] | null, background: Interval | null): Interval | null {
  if (!colours?.length || (!background && colours.some((colour) => colour.alpha !== 1))) return null;
  const values = colours.flatMap(({ value, alpha }) =>
    (background ?? [0, 0]).map((base) => value * alpha + base * (1 - alpha)),
  );
  return [Math.min(...values), Math.max(...values)];
}
function backdrop(node: Element) {
  const ancestry: Element[] = [];
  for (let current: Element | null = node; current; current = current.parentElement) {
    if (ancestry.length >= motionLimits.collectionVisuals) return null;
    ancestry.push(current);
  }
  let interval: Interval | null = null;
  for (const current of ancestry.reverse()) {
    const values = colours(current, "background-color");
    if (!values) return null;
    if (!interval && values.every((value) => value.alpha === 0)) continue;
    interval = composite(values, interval);
    if (!interval) return null;
  }
  return interval;
}

